static int load_volume(void)
{
  FILE *file;
  char buffer[128];
  size_t nread;
  const char *found;
  int value = 70;

  file = fopen(VOLUME_FILE, "r");
  if (file == NULL)
    {
      return value;
    }

  nread = fread(buffer, 1, sizeof(buffer) - 1, file);
  fclose(file);

  if (nread == 0)
    {
      return value;
    }

  buffer[nread] = '\0';

  found = strstr(buffer, "\"volume\"");
  if (found != NULL)
    {
      found = strchr(found, ':');
      if (found != NULL)
        {
          int parsed = atoi(found + 1);

          if (parsed >= 0 && parsed <= 100)
            {
              value = parsed;
            }
        }
    }

  return value;
}

