static bool g_speaking;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static bool ensure_channel(void)
{
  if (g_channel_ready)
    {
      return true;
    }

  if (voice_channel_init() == 0)
    {
      g_channel_ready = true;
    }

  return g_channel_ready;
}

static void *speak_worker(void *arg)
{
  (void)arg;

  for (; ; )
    {
      char text[SPEAK_TEXT_MAX];

      pthread_mutex_lock(&g_speak_lock);

      while (g_speak_count == 0)
        {
          pthread_cond_wait(&g_speak_cond, &g_speak_lock);
        }

      memcpy(text, g_speak_queue[g_speak_head], sizeof(text));
      g_speak_head = (g_speak_head + 1) % SPEAK_SLOTS;
      g_speak_count--;
      g_speaking = true;

      pthread_mutex_unlock(&g_speak_lock);

      /* Blocks for the duration of synthesis and playback. */

      if (voice_channel_speak(text) != 0)
        {
          syslog(LOG_WARNING, "[ui_voice] TTS failed\n");
        }

      pthread_mutex_lock(&g_speak_lock);
      g_speaking = false;
      pthread_mutex_unlock(&g_speak_lock);
    }

  return NULL;
}

static bool ensure_speak_worker(void)
{
  pthread_attr_t attr;
  pthread_t tid;
  struct sched_param param;

  if (g_speak_worker_started)
    {
      return true;
    }

  if (!g_speak_cond_ready)
    {
      if (pthread_cond_init(&g_speak_cond, NULL) != 0)
        {
          syslog(LOG_ERR, "[ui_voice] cond init failed\n");
          return false;
        }

      g_speak_cond_ready = true;
    }

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, SPEAK_STACK);

  /* study_terminal runs at SCHED_PRIORITY_DEFAULT (100). Synthesis must sit
   * below that or it starves the display; 50 matches AGENT_VOICE_PRIO, the
   * priority ai_agent uses for its own voice threads.
   */

  param.sched_priority = SPEAK_PRIO;
  pthread_attr_setschedparam(&attr, &param);
  pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);

  if (pthread_create(&tid, &attr, speak_worker, NULL) != 0)
    {
      pthread_attr_destroy(&attr);
      syslog(LOG_ERR, "[ui_voice] cannot start TTS worker\n");
      return false;
    }

  pthread_attr_destroy(&attr);
  pthread_detach(tid);
  g_speak_worker_started = true;
  return true;
}

