 *
 * Called only on handshake failure, so it costs nothing in the normal path.
 * The question it answers: did we receive a well-formed DER certificate that
 * the parser rejected, or did we receive something that is not a certificate
 * at all?  A real X.509 chain opens with 30 82 <len> (SEQUENCE, long form).
 * Anything else -- zeros, ASCII, stale heap contents -- means the buffer was
 * corrupted and the ASN.1 error is a symptom, not the fault.
 */

static void tls_dump_peer_cert(tls_ctx_t* ctx)
{
    const mbedtls_x509_crt* crt = mbedtls_ssl_get_peer_cert(&ctx->ssl);

    if (!crt) {
        /* No certificate stored.  Either the server never sent one, or the
         * failure happened before mbedTLS could keep it -- which is itself
         * the answer we are looking for.
         */
        syslog(LOG_ERR, "[%s] DIAG: no peer cert retained\\n", TAG);
        return;
    }

    syslog(LOG_ERR, "[%s] DIAG: peer cert raw len=%u\\n", TAG,
        (unsigned)crt->raw.len);

