        }

        syslog(LOG_ERR, "[%s] DIAG: first %u bytes: %s\\n", TAG,
            (unsigned)n, hex);

        /* Say it plainly so the log is readable without a DER reference. */

        if (crt->raw.p[0] == 0x30) {
