                            "real DER, suspect the parser or the chain\\n", TAG);
        } else {
            syslog(LOG_ERR, "[%s] DIAG: does NOT open with 0x30 - buffer is "
                            "corrupted, not a certificate problem\\n", TAG);
        }
    }
}

